const out = R.map(r => {
  const [blat, blng] = BASE[r.district];
  const dlat = ((r.id % 19) - 9) * 0.0005;
  const dlng = ((r.id % 17) - 8) * 0.0005;
  return {
    id: r.id,
    name: r.name,
    description: r.description,
    priceRange: r.priceRange,
    priceMin: r.priceMin,
    priceMax: r.priceMax,
    budgetCategory: r.budget,
    address: r.address,
    district: r.district,
    type: r.type,
    typeStandard: r.typeStandard,
    emoji: r.emoji,
    hours: r.hours,
    hoursCategory: r.hoursCategory,
    dishes: r.dishes,
    lat: +(blat + dlat).toFixed(4),
    lng: +(blng + dlng).toFixed(4),
    rating: r.rating,
    reviewCount: r.reviewCount,
    pexelsImage: img(r.typeStandard, r.id)
  };
});

fs.writeFileSync(path.join(__dirname, 'restaurants.json'), JSON.stringify(out, null, 2));
console.log('wrote', out.length, 'restaurants');
// quick integrity report
const types = [...new Set(out.map(o=>o.typeStandard))].sort();
const districts = [...new Set(out.map(o=>o.district))].sort();
console.log('typeStandard values:', types.join(', '));
console.log('distinct districts ('+districts.length+'):', districts.join(', '));
